package config

import (
	"bytes"
	"fmt"

	"gopkg.in/yaml.v3"
)

// MinimalConfig represents the clean, human-readable configuration generated by 'noctifab init'.
// All omitted fields automatically inherit runtime defaults from config.DefaultConfig().
type MinimalConfig struct {
	ConfigVersion string                `yaml:"config_version"`
	VCS           MinimalVCSConfig      `yaml:"vcs"`
	Sandbox       MinimalSandboxConfig  `yaml:"sandbox"`
	LLM           MinimalLLMConfig      `yaml:"llm"`
	LLMs          []MinimalLLMConfig    `yaml:"llms,omitempty"`
	Agents        *MinimalAgentsConfig  `yaml:"agents,omitempty"`
	Context       *MinimalContextConfig `yaml:"context,omitempty"`
	Runtime       *MinimalRuntimeConfig `yaml:"runtime,omitempty"`
	Storage       *MinimalStorageConfig `yaml:"storage,omitempty"`
}

// MinimalVCSConfig holds essential VCS repository and branching settings.
type MinimalVCSConfig struct {
	Provider     string `yaml:"provider,omitempty"`
	Repository   string `yaml:"repository"`
	BaseBranch   string `yaml:"base_branch,omitempty"`
	UseWorktrees bool   `yaml:"use_worktrees"`
}

// MinimalSandboxConfig holds essential sandbox test, format, and lint commands.
type MinimalSandboxConfig struct {
	Mode              string               `yaml:"mode,omitempty"`
	TestCommand       string               `yaml:"test_command"`
	FormatterCommand  string               `yaml:"formatter_command"`
	TimeoutSeconds    int                  `yaml:"timeout_seconds,omitempty"`
	Linter            *MinimalLinterConfig `yaml:"linter,omitempty"`
	ForbiddenPatterns []string             `yaml:"forbidden_patterns,omitempty"`
}

// MinimalLinterConfig holds deterministic linter command configuration.
type MinimalLinterConfig struct {
	Command   string `yaml:"command"`
	MaxIssues int    `yaml:"max_issues,omitempty"`
}

// MinimalLLMConfig holds primary LLM provider and model settings.
type MinimalLLMConfig struct {
	Provider    string   `yaml:"provider"`
	Model       string   `yaml:"model"`
	URL         string   `yaml:"url,omitempty"`
	Temperature *float64 `yaml:"temperature,omitempty"`
	MaxTimeout  Duration `yaml:"max_timeout,omitempty"`
}

// MinimalAgentsConfig holds agent overrides when deviating from defaults.
type MinimalAgentsConfig struct {
	Architecture string           `yaml:"architecture,omitempty"`
	QA           *MinimalQAConfig `yaml:"qa,omitempty"`
}

// MinimalQAConfig holds QA build command overrides.
type MinimalQAConfig struct {
	BuildCommand []string `yaml:"build_command,omitempty"`
}

// MinimalContextConfig holds AST context compaction settings.
type MinimalContextConfig struct {
	Compaction string `yaml:"compaction,omitempty"`
}

// MinimalRuntimeConfig holds loop and runtime limit overrides.
type MinimalRuntimeConfig struct {
	Loops int `yaml:"loops,omitempty"`
}

// MinimalStorageConfig holds database storage provider overrides.
type MinimalStorageConfig struct {
	Provider   string `yaml:"provider,omitempty"`
	ConnString string `yaml:"conn_string,omitempty"`
}

// BuildMinimalConfig converts a full Config into its minimal representation.
func BuildMinimalConfig(cfg *Config) MinimalConfig {
	if cfg == nil {
		cfg = DefaultConfig()
	}

	def := DefaultConfig()

	vcsProvider := cfg.VCS.Provider
	if vcsProvider == "" {
		vcsProvider = def.VCS.Provider
	}
	vcsRepo := cfg.VCS.Repository
	if vcsRepo == "" {
		vcsRepo = def.VCS.Repository
	}
	baseBranch := cfg.VCS.BaseBranch
	if baseBranch == "" {
		baseBranch = def.VCS.BaseBranch
	}

	sandboxMode := cfg.Sandbox.Mode
	if sandboxMode == "" {
		sandboxMode = def.Sandbox.Mode
	}
	testCmd := cfg.Sandbox.TestCommand
	if testCmd == "" {
		testCmd = def.Sandbox.TestCommand
	}

	llmProvider := cfg.LLM.Provider
	if llmProvider == "" {
		llmProvider = def.LLM.Provider
	}
	llmModel := cfg.LLM.Model
	if llmModel == "" {
		llmModel = def.LLM.Model
	}

	temp := cfg.LLM.Temperature
	minimalLLM := MinimalLLMConfig{
		Provider:    llmProvider,
		Model:       llmModel,
		URL:         cfg.LLM.URL,
		Temperature: &temp,
	}
	if cfg.LLM.MaxTimeout != 0 && cfg.LLM.MaxTimeout != def.LLM.MaxTimeout {
		minimalLLM.MaxTimeout = cfg.LLM.MaxTimeout
	}

	minimalSandbox := MinimalSandboxConfig{
		Mode:             sandboxMode,
		TestCommand:      testCmd,
		FormatterCommand: cfg.Sandbox.FormatterCommand,
	}
	if cfg.Sandbox.TimeoutSeconds != 0 && cfg.Sandbox.TimeoutSeconds != def.Sandbox.TimeoutSeconds {
		minimalSandbox.TimeoutSeconds = cfg.Sandbox.TimeoutSeconds
	}
	if cfg.Sandbox.Linter.Command != nil && *cfg.Sandbox.Linter.Command != "" {
		maxIssues := 0
		if cfg.Sandbox.Linter.MaxIssues != nil {
			maxIssues = *cfg.Sandbox.Linter.MaxIssues
		}
		minimalSandbox.Linter = &MinimalLinterConfig{
			Command:   *cfg.Sandbox.Linter.Command,
			MaxIssues: maxIssues,
		}
	} else if cfg.Sandbox.LinterCommand != nil && *cfg.Sandbox.LinterCommand != "" {
		maxIssues := 0
		if cfg.Sandbox.MaxLinterIssues != nil {
			maxIssues = *cfg.Sandbox.MaxLinterIssues
		}
		minimalSandbox.Linter = &MinimalLinterConfig{
			Command:   *cfg.Sandbox.LinterCommand,
			MaxIssues: maxIssues,
		}
	}
	if len(cfg.Sandbox.ForbiddenPatterns) > 0 {
		minimalSandbox.ForbiddenPatterns = cfg.Sandbox.ForbiddenPatterns
	}

	minimal := MinimalConfig{
		ConfigVersion: "2.0",
		VCS: MinimalVCSConfig{
			Provider:     vcsProvider,
			Repository:   vcsRepo,
			BaseBranch:   baseBranch,
			UseWorktrees: cfg.VCS.UseWorktrees,
		},
		Sandbox: minimalSandbox,
		LLM:     minimalLLM,
	}

	if len(cfg.LLMs) > 1 {
		for _, l := range cfg.LLMs {
			t := l.Temperature
			item := MinimalLLMConfig{
				Provider:    l.Provider,
				Model:       l.Model,
				URL:         l.URL,
				Temperature: &t,
			}
			if l.MaxTimeout != 0 && l.MaxTimeout != def.LLM.MaxTimeout {
				item.MaxTimeout = l.MaxTimeout
			}
			minimal.LLMs = append(minimal.LLMs, item)
		}
	}

	// Context overrides (e.g. from profiles)
	if cfg.Context.Compaction != "" && cfg.Context.Compaction != "none" {
		minimal.Context = &MinimalContextConfig{
			Compaction: cfg.Context.Compaction,
		}
	}

	// Agents overrides
	var minimalAgents *MinimalAgentsConfig
	if cfg.Agents.Architecture != "" && cfg.Agents.Architecture != def.Agents.Architecture {
		minimalAgents = &MinimalAgentsConfig{
			Architecture: cfg.Agents.Architecture,
		}
	}
	if len(cfg.Agents.QA.BuildCommand) > 0 && !slicesEqual(cfg.Agents.QA.BuildCommand, def.Agents.QA.BuildCommand) {
		if minimalAgents == nil {
			minimalAgents = &MinimalAgentsConfig{}
		}
		minimalAgents.QA = &MinimalQAConfig{
			BuildCommand: cfg.Agents.QA.BuildCommand,
		}
	}
	minimal.Agents = minimalAgents

	// Runtime overrides (e.g. loops)
	if loops := cfg.Runtime.GetLoops(); loops > 1 {
		minimal.Runtime = &MinimalRuntimeConfig{
			Loops: loops,
		}
	}

	// Storage overrides
	if (cfg.Storage.Provider != "" && cfg.Storage.Provider != def.Storage.Provider) ||
		(cfg.Storage.ConnString != "" && cfg.Storage.ConnString != def.Storage.ConnString) {
		minimal.Storage = &MinimalStorageConfig{
			Provider:   cfg.Storage.Provider,
			ConnString: cfg.Storage.ConnString,
		}
	}

	return minimal
}

// GenerateMinimalConfigYAML produces formatted YAML bytes for a minimal configuration file.
// It includes explanatory comments noting that omitted fields inherit runtime defaults.
func GenerateMinimalConfigYAML(cfg *Config) ([]byte, error) {
	minimal := BuildMinimalConfig(cfg)

	raw, err := yaml.Marshal(minimal)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal minimal config: %w", err)
	}

	var buf bytes.Buffer
	buf.WriteString("# Noctifab Project Configuration\n")
	buf.WriteString("# Generated by 'noctifab init'. Omitted settings inherit defaults from Noctifab runtime.\n")
	buf.WriteString("# For schema documentation and available configuration options, see SPEC.md and docs/configuration.md.\n\n")
	buf.Write(raw)

	return buf.Bytes(), nil
}

func slicesEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
